(function(){
  const MODE="real-workforce-v1",now=()=>new Date().toISOString(),safe=v=>String(v??"").replace(/[<>]/g,"").trim(),esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
  const initial=()=>({meta:{mode:MODE,started:false,status:"NO_WORK",createdAt:now()},employees:[
    {id:"sara",name:"سارة",role:"المدير العام AI",department:"إدارة المشاريع",project:"",projectIds:[],task:"جاهزة لاستقبال توجيه نواف",status:"READY",progress:0,productivity:0,permissions:"AUTO_INTERNAL",responsibilities:"تنسيق الأهداف وتوزيع العمل ورفع القرارات المهمة",instructions:"لا تسجلي أي إنجاز بلا دليل",history:[],completedTaskIds:[]},
    {id:"omar",name:"عمر",role:"باحث ومنفذ تقني",department:"التقنية والتطوير",project:"",projectIds:[],task:"جاهز",status:"READY",progress:0,productivity:0,permissions:"AUTO_INTERNAL",responsibilities:"فحص المصادر والمستودعات وإنتاج نتائج قابلة للتحقق",instructions:"اربط كل نتيجة بمصدر",history:[],completedTaskIds:[]},
    {id:"lian",name:"ليان",role:"مصممة تجربة ومنتج",department:"التصميم",project:"",projectIds:[],task:"جاهزة",status:"READY",progress:0,productivity:0,permissions:"AUTO_INTERNAL",responsibilities:"مراجعة تجربة الاستخدام والمخرجات البصرية",instructions:"لا تدعي مراجعة واجهة لم يتم فتحها",history:[],completedTaskIds:[]},
    {id:"noura",name:"نورة",role:"مراجعة جودة وبيانات",department:"التحليلات",project:"",projectIds:[],task:"جاهزة",status:"READY",progress:0,productivity:0,permissions:"AUTO_INTERNAL",responsibilities:"التحقق من الأدلة ومراجعة التقارير",instructions:"افصلي الحقائق عن الاستنتاجات",history:[],completedTaskIds:[]}
  ],projects:[{id:"q",name:"قدّها",phase:"لم يبدأ العمل",progress:0,health:0,manager:"sara",team:[],issues:[],departmentRequests:[]},{id:"m",name:"مُعِين",phase:"لم يبدأ العمل",progress:0,health:0,manager:"sara",team:[],issues:[],departmentRequests:[]}],tasks:[],reports:[],decisions:[],activities:[],requests:[],rules:[{id:"spend",scope:"الشركة",text:"ممنوع أي إنفاق دون موافقة نواف الصريحة",level:"FINANCIAL",locked:true},{id:"mueen-content",scope:"مُعِين",text:"تغييرات المحتوى الديني تتطلب مراجعة الرئيس التنفيذي",level:"APPROVAL_REQUIRED",locked:true}],commands:[],discussions:[{id:"company",type:"COMPANY",title:"مجلس الشركة",project:null,department:null,participants:["nawaf","sara","omar","lian","noura"],messages:[]}],artifacts:[],proposals:[],integrations:[{id:"github-public",name:"GitHub العام",status:"AVAILABLE",mode:"READ_ONLY",cost:"$0"},{id:"ai-model",name:"نموذج AI",status:"NOT_CONNECTED",mode:"DISABLED",cost:"غير مفعل"}]});
  if(!state.meta||state.meta.mode!==MODE){state=initial();save();}
  state.commands=state.commands||[];state.discussions=state.discussions||[];state.artifacts=state.artifacts||[];state.proposals=state.proposals||[];state.integrations=state.integrations||[];
  const employee=id=>emp(id),project=id=>pr(id),clock=v=>new Date(v).toLocaleTimeString("ar-SA",{hour:"2-digit",minute:"2-digit"});
  function audit(text,kind="REAL",links={}){const e={id:"audit-"+Date.now()+Math.random().toString(16).slice(2),text,kind,createdAt:now(),links};state.activities.unshift(e);if(links.employee){const w=employee(links.employee);if(w){w.history.unshift({at:e.createdAt,text});}}return e;}
  function roomFor(projectId){let room=state.discussions.find(x=>x.type==="PROJECT"&&x.project===projectId);if(!room){room={id:"room-"+projectId,type:"PROJECT",title:"غرفة مشروع "+project(projectId).name,project:projectId,department:null,participants:["nawaf","sara"],messages:[]};state.discussions.push(room);}return room;}
  function message(room,author,text,type="MESSAGE",links={}){const m={id:"msg-"+Date.now()+Math.random().toString(16).slice(2),author,text,createdAt:now(),type,links};room.messages.push(m);return m;}
  function progress(task){task.progress=task.steps.length?Math.round(task.steps.filter(s=>s.done).length/task.steps.length*100):0;}
  function modalOpen(html){modal('<div class="dialog-wide">'+html+'</div>');document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>$("#modal").classList.remove("open"));}
  const close='<button class="dialog-close" data-close>إغلاق</button>';

  function commandView(){modalOpen('<div class="workspace-head"><div><h2>توجيه الشركة</h2><p class="muted">لن يبدأ أي نشاط قبل توجيه حقيقي من نواف.</p></div>'+close+'</div><form id="ceo-command" class="command-form"><label>ماذا تريد من الفريق؟</label><textarea name="goal" required placeholder="مثال: راجعوا مستودع قدّها وحددوا المشاكل القابلة للإثبات"></textarea><div class="form-grid"><label>المشروع<select name="project"><option value="q">قدّها</option><option value="m">مُعِين</option></select></label><label>مصدر GitHub عام — اختياري<input name="repository" placeholder="https://github.com/owner/repository"></label></div><div class="truth-note">إذا أضفت مستودعًا عامًا سيجلب النظام بياناته فعليًا بوضع القراءة فقط. بدون مصدر لن يدّعي الفريق أنه راجع ملفات.</div><button class="primary">بسم الله — ابدأ العمل</button></form>');$("#ceo-command").onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),goal=safe(form.get("goal")),projectId=safe(form.get("project")),repository=safe(form.get("repository"));await createCommand({goal,projectId,repository});};}
  async function createCommand({goal,projectId,repository}){const id="cmd-"+Date.now(),cmd={id,goal,project:projectId,repository,status:"ACTIVE",createdAt:now()},p=project(projectId),room=roomFor(projectId);state.meta.started=true;state.meta.status="ACTIVE";state.commands.unshift(cmd);p.phase="تحليل توجيه نواف";if(!p.team.includes("sara"))p.team.push("sara");message(room,"nawaf",goal,"CEO_COMMAND",{command:id});message(room,"sara","تم استلام التوجيه. سأشغّل فقط المهام التي لها مصدر أو مخرج قابل للتحقق.","COORDINATION",{command:id});audit("نواف أصدر توجيهًا جديدًا لمشروع "+p.name,"REAL",{project:projectId,discussion:room.id,command:id});if(repository){const task={id:"task-"+Date.now(),title:"فحص المستودع المرتبط بالتوجيه",employee:"omar",project:projectId,command:id,status:"READY",progress:0,source:repository,tools:["GitHub Public API — read only"],steps:[{id:"connect",title:"الاتصال بالمصدر",done:false},{id:"tree",title:"قراءة شجرة الملفات",done:false},{id:"facts",title:"استخراج الحقائق",done:false},{id:"report",title:"حفظ التقرير",done:false},{id:"review",title:"مراجعة الدليل",done:false}],history:[]};state.tasks.push(task);if(!p.team.includes("omar"))p.team.push("omar");employee("omar").project=p.name;employee("omar").projectIds=[projectId];employee("omar").task=task.title;employee("omar").status="READY";message(room,"sara","أنشأت مهمة فحص مرتبطة بالمصدر وأسندتها إلى عمر. التقدم الآن 0 من 5 خطوات.","TASK_CREATED",{task:task.id});audit("تم إنشاء مهمة حقيقية لعمر مع مصدر GitHub","REAL",{employee:"omar",project:projectId,task:task.id,discussion:room.id});save();render();toast("تم إنشاء المهمة دون تقدم وهمي");await runRepositoryTask(task.id);}else{message(room,"sara","لا يوجد مصدر متصل بعد. أحتاج رابط مستودع أو ملفات قبل ادعاء أي مراجعة.","BLOCKED",{command:id});audit("التوجيه ينتظر مصدرًا قابلًا للفحص","APPROVAL",{project:projectId,discussion:room.id,command:id});save();render();toast("تم حفظ التوجيه وهو ينتظر مصدرًا");}}
  async function runRepositoryTask(id){const task=state.tasks.find(x=>x.id===id),worker=employee(task.employee),room=roomFor(task.project);try{task.status="RESEARCHING";worker.status="RESEARCHING";worker.task=task.title;task.steps[0].done=true;progress(task);task.history.unshift({at:now(),text:"بدأ اتصال القراءة فقط مع GitHub"});audit(worker.name+" بدأ فحص المصدر المرتبط بالمهمة","REAL",{employee:worker.id,project:task.project,task:id,discussion:room.id});save();render();const result=await NawafAdapters.githubPublic.inspectRepository(task.source);task.steps[1].done=true;task.steps[2].done=true;progress(task);const artifact={id:"artifact-"+Date.now(),type:"REPOSITORY_AUDIT",title:"فحص مستودع "+result.repository,author:worker.id,task:id,project:task.project,sources:[result.sourceUrl],context:state.commands.find(x=>x.id===task.command)?.goal||"",findings:result.findings,recommendations:result.recommendations,evidence:result.evidence,rawSummary:{fileCount:result.fileCount,defaultBranch:result.defaultBranch,languages:result.languages},createdAt:now(),reviewHistory:[],discussion:room.id,status:"READY_FOR_REVIEW"};state.artifacts.push(artifact);const report={id:"report-"+Date.now(),title:artifact.title,author:worker.id,department:worker.department,task:id,project:task.project,sources:artifact.sources,artifact:artifact.id,status:"المراجعة",stage:"المراجعة",progress:80,content:[...artifact.findings,...artifact.recommendations].join("\n"),createdAt:artifact.createdAt,updatedAt:now(),completedAt:null,history:[{at:now(),stage:"جمع البيانات",progress:20},{at:now(),stage:"التحليل",progress:60},{at:now(),stage:"إعداد التقرير",progress:80}]};state.reports.push(report);task.steps[3].done=true;progress(task);message(room,worker.id,"أنهيت فحص المستودع من GitHub. وجدت "+result.fileCount+" ملفًا، وحفظت الحقائق والتوصيات في مخرج قابل للفتح.","EVIDENCE",{task:id,artifact:artifact.id,report:report.id});audit(worker.name+" حفظ فحصًا فعليًا للمستودع مع الأدلة","REAL",{employee:worker.id,project:task.project,task:id,artifact:artifact.id,report:report.id,discussion:room.id});await reviewArtifact(artifact,task,room);if(artifact.status==="REVIEWED"){report.status="مكتمل";report.stage="مكتمل";report.progress=100;report.completedAt=now();report.updatedAt=report.completedAt;report.history.push({at:report.completedAt,stage:"المراجعة",progress:90},{at:report.completedAt,stage:"مكتمل",progress:100});}save();render();toast("اكتمل الفحص والمراجعة بدليل قابل للفتح");}catch(error){task.status="BLOCKED";worker.status="READY";task.error=safe(error.message);task.history.unshift({at:now(),text:"تعذر الوصول للمصدر: "+task.error});message(room,worker.id,"تعذر فحص المصدر: "+task.error,"BLOCKED",{task:id});audit("تعذر فحص المصدر ولم يُسجل أي إنجاز","APPROVAL",{employee:worker.id,project:task.project,task:id,discussion:room.id});save();render();toast(task.error);}}
  async function reviewArtifact(artifact,task,room){const reviewer=employee("noura");reviewer.project=project(task.project).name;reviewer.projectIds=[task.project];reviewer.task="مراجعة أدلة "+artifact.title;reviewer.status="REVIEWING";if(!project(task.project).team.includes("noura"))project(task.project).team.push("noura");const checks=[artifact.sources.length>0,Number.isFinite(artifact.rawSummary.fileCount),Array.isArray(artifact.findings)&&artifact.findings.length>0],passed=checks.filter(Boolean).length;artifact.reviewHistory.push({reviewer:reviewer.id,createdAt:now(),checks:checks.length,passed,note:passed===checks.length?"اكتملت فحوص اتساق الدليل":"المخرج يحتاج استكمال الدليل"});artifact.status=passed===checks.length?"REVIEWED":"CHANGES_REQUIRED";task.steps[4].done=passed===checks.length;progress(task);task.status=task.progress===100?"COMPLETED":"REVIEWING";workerDone(task.employee,task);reviewer.status="READY";reviewer.task="جاهزة";message(room,reviewer.id,"راجعت المخرج آليًا: "+passed+" من "+checks.length+" فحوص دليل نجحت. لم أضف ادعاءات خارج البيانات المحفوظة.","REVIEW",{task:task.id,artifact:artifact.id});audit("نورة راجعت أدلة المخرج وحفظت نتيجة المراجعة","REAL",{employee:"noura",project:task.project,task:task.id,artifact:artifact.id,discussion:room.id});if(passed===checks.length&&artifact.recommendations.length){const proposal={id:"proposal-"+Date.now(),title:artifact.recommendations[0],author:task.employee,project:task.project,why:"ناتج مباشر من فحص "+artifact.title,evidence:[artifact.id],benefit:"رفع قابلية التحقق وجودة المشروع",risk:"منخفض",effort:"يُحدد بعد مناقشة نواف",status:"DISCUSSION",discussion:room.id,createdAt:now()};state.proposals.push(proposal);message(room,"sara","هناك توصية مبنية على الفحص ويمكن تحويلها إلى قرار بعد مناقشتك: "+proposal.title,"PROPOSAL",{proposal:proposal.id,artifact:artifact.id});audit("تم إنشاء مقترح مبني على دليل للمراجعة مع نواف","REAL",{project:task.project,proposal:proposal.id,artifact:artifact.id,discussion:room.id});}}
  function workerDone(id,task){const w=employee(id);w.status=task.progress===100?"READY":"REVIEWING";w.progress=task.progress;w.completedTaskIds=w.completedTaskIds||[];if(task.progress===100&&!w.completedTaskIds.includes(task.id))w.completedTaskIds.push(task.id);w.productivity=Math.round(state.tasks.filter(t=>t.employee===id&&t.status==="COMPLETED").length/Math.max(1,state.tasks.filter(t=>t.employee===id).length)*100);const p=project(task.project),pt=state.tasks.filter(t=>t.project===p.id);p.progress=pt.length?Math.round(pt.reduce((n,t)=>n+t.progress,0)/pt.length):0;p.health=p.progress;p.phase=task.progress===100?"نتائج جاهزة للمراجعة":"عمل فعلي جارٍ";}

  function artifactView(id){const a=state.artifacts.find(x=>x.id===id);if(!a)return;const review=a.reviewHistory?.[a.reviewHistory.length-1];modalOpen('<div class="workspace-head"><div><h2>'+esc(a.title)+'</h2><p class="muted">مخرج فعلي · '+esc(employee(a.author)?.name)+' · '+esc(project(a.project)?.name)+'</p></div><span class="badge real">'+esc(a.status)+'</span>'+close+'</div><div class="evidence-strip"><b>المصدر</b>'+a.sources.map(s=>'<a href="'+esc(s)+'" target="_blank" rel="noopener">'+esc(s)+'</a>').join('')+'</div><div class="detail-grid"><div class="detail-box"><b>'+a.rawSummary.fileCount+'</b><small>ملفات مقروءة</small></div><div class="detail-box"><b>'+esc(a.rawSummary.defaultBranch)+'</b><small>الفرع</small></div><div class="detail-box"><b>'+(review?review.passed+'/'+review.checks:'—')+'</b><small>فحوص المراجعة</small></div></div><div class="split"><section><h3>حقائق ونتائج</h3>'+a.findings.map(x=>'<div class="finding">'+esc(x)+'</div>').join('')+'</section><section><h3>توصيات</h3>'+a.recommendations.map(x=>'<div class="finding recommendation">'+esc(x)+'</div>').join('')+'</section></div><h3>سياق التوجيه</h3><p>'+esc(a.context)+'</p><button class="secondary-action" id="open-related-discussion">فتح النقاش المرتبط</button>');$("#open-related-discussion").onclick=()=>discussionView(a.discussion);}
  function discussionView(id){const room=state.discussions.find(x=>x.id===id);if(!room)return;modalOpen('<div class="workspace-head"><div><h2>'+esc(room.title)+'</h2><p class="muted">'+esc(room.type)+' · '+room.messages.length+' رسائل موثقة</p></div>'+close+'</div><div class="chat-log">'+(room.messages.length?room.messages.map(m=>'<article class="chat-message '+(m.author==='nawaf'?'from-ceo':'')+'"><header><b>'+esc(m.author==='nawaf'?'نواف':employee(m.author)?.name||'المدير العام')+'</b><time>'+clock(m.createdAt)+'</time></header><p>'+esc(m.text)+'</p><div class="message-links">'+(m.links?.artifact?'<button data-artifact="'+m.links.artifact+'">فتح الدليل</button>':'')+(m.links?.task?'<button data-task="'+m.links.task+'">فتح المهمة</button>':'')+(m.links?.proposal?'<button data-proposal="'+m.links.proposal+'">فتح المقترح</button>':'')+'</div></article>').join(''):'<div class="empty-state">لا توجد محادثات وهمية. ابدأ بتوجيه أو رسالة.</div>')+'</div><form id="chat-reply" class="chat-compose"><textarea name="message" required placeholder="شارك الفريق أو اسأل عن الدليل..."></textarea><button class="primary">إرسال باسم نواف</button></form>');document.querySelectorAll('[data-artifact]').forEach(x=>x.onclick=()=>artifactView(x.dataset.artifact));document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskDetail(x.dataset.task));document.querySelectorAll('[data-proposal]').forEach(x=>x.onclick=()=>proposalView(x.dataset.proposal));$("#chat-reply").onsubmit=e=>{e.preventDefault();const text=safe(new FormData(e.target).get("message"));message(room,"nawaf",text,"CEO_MESSAGE");audit("نواف شارك في "+room.title,"REAL",{project:room.project,discussion:room.id});save();discussionView(room.id);};}
  function taskDetail(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;modalOpen('<div class="workspace-head"><div><h2>'+esc(t.title)+'</h2><p class="muted">'+esc(employee(t.employee)?.name)+' · '+esc(project(t.project)?.name)+'</p></div><span class="badge real">'+t.steps.filter(s=>s.done).length+' / '+t.steps.length+' خطوات</span>'+close+'</div><div class="bar large"><i style="width:'+t.progress+'%"></i></div><div class="step-list">'+t.steps.map(s=>'<div class="task-check '+(s.done?'done':'')+'"><i>'+(s.done?'✓':'○')+'</i><span>'+esc(s.title)+'</span></div>').join('')+'</div><h3>الأدوات والسياق</h3><div class="workspace-badges">'+(t.tools||[]).map(x=>'<span class="badge">'+esc(x)+'</span>').join('')+'</div>'+(t.error?'<div class="truth-note error">'+esc(t.error)+'</div>':'')+'<h3>السجل</h3><div class="timeline">'+(t.history||[]).map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.text)+'</span></div>').join('')+'</div>');}
  function proposalView(id){const p=state.proposals.find(x=>x.id===id);if(!p)return;modalOpen('<div class="workspace-head"><div><h2>'+esc(p.title)+'</h2><p class="muted">مقترح من '+esc(employee(p.author)?.name)+' · '+esc(project(p.project)?.name)+'</p></div><span class="badge wait">'+esc(p.status)+'</span>'+close+'</div><div class="detail-grid"><div class="detail-box"><b>'+esc(p.benefit)+'</b><small>الفائدة</small></div><div class="detail-box"><b>'+esc(p.risk)+'</b><small>المخاطر</small></div><div class="detail-box"><b>'+esc(p.effort)+'</b><small>الجهد</small></div></div><h3>لماذا ظهر المقترح؟</h3><p>'+esc(p.why)+'</p><div class="buttons"><button class="ok" data-proposal-action="approve">اعتماد كمهمة</button><button data-proposal-action="discuss">ناقش أكثر</button><button data-proposal-action="changes">طلب تعديل</button><button data-proposal-action="reject">رفض</button></div>');document.querySelectorAll('[data-proposal-action]').forEach(x=>x.onclick=()=>proposalAction(p,x.dataset.proposalAction));}
  function proposalAction(p,action){if(action==='discuss')return discussionView(p.discussion);p.status=action==='approve'?'APPROVED':action==='changes'?'CHANGES_REQUESTED':'REJECTED';if(action==='approve'){const t={id:'follow-'+Date.now(),title:p.title,employee:p.author,project:p.project,status:'READY',progress:0,source:null,tools:[],steps:[{id:'scope',title:'تحديد النطاق والأدلة المطلوبة',done:false}],history:[]};state.tasks.push(t);employee(p.author).status='READY';employee(p.author).task=t.title;audit('نواف اعتمد المقترح وحوّله إلى مهمة حقيقية','REAL',{project:p.project,task:t.id,proposal:p.id});}else audit('نواف حدّث حالة المقترح إلى '+p.status,'REAL',{project:p.project,proposal:p.id});save();render();toast('تم تحديث المقترح');}
  function companyChat(){discussionView("company");}

  const baseRender=window.render,baseEmployee=window.employee,baseProject=window.project,baseDepartment=window.department;
  window.employee=function(id){baseEmployee(id);if(!id)return;const e=employee(id),dialog=document.querySelector('#dialog .dialog-wide');if(dialog){const tasks=state.tasks.filter(t=>t.employee===id),artifacts=state.artifacts.filter(a=>a.author===id),panel=document.createElement('section');panel.className='access-panel';panel.innerHTML='<h3>الأدوات والسياق المستخدم</h3><div class="workspace-badges">'+([...new Set(tasks.flatMap(t=>t.tools||[]))].map(x=>'<span class="badge real">'+esc(x)+'</span>').join('')||'<span class="badge">لا توجد أداة مستخدمة بعد</span>')+'</div><h3>المخرجات الفعلية</h3>'+(artifacts.map(a=>'<button class="secondary-action" data-employee-artifact="'+a.id+'">'+esc(a.title)+'</button>').join('')||'<p class="muted">لا توجد مخرجات حتى الآن.</p>');dialog.appendChild(panel);panel.querySelectorAll('[data-employee-artifact]').forEach(x=>x.onclick=()=>artifactView(x.dataset.employeeArtifact));const b=document.createElement('button');b.className='secondary-action';b.textContent='محادثة مباشرة مع '+e.name;b.onclick=()=>{let room=state.discussions.find(r=>r.type==='DIRECT'&&r.participants.includes(id));if(!room){room={id:'direct-'+id,type:'DIRECT',title:'محادثة نواف مع '+e.name,project:e.projectIds[0]||null,department:e.department,participants:['nawaf',id],messages:[]};state.discussions.push(room);save();}discussionView(room.id)};dialog.appendChild(b);}}
  window.project=function(id){baseProject(id);const dialog=document.querySelector('#dialog .dialog-wide');if(dialog){const b=document.createElement('button');b.className='secondary-action';b.textContent='فتح غرفة المشروع';b.onclick=()=>discussionView(roomFor(id).id);dialog.appendChild(b);}}
  window.department=function(name){baseDepartment(name);const dialog=document.querySelector('#dialog .dialog-wide');if(dialog){const b=document.createElement('button');b.className='secondary-action';b.textContent='فتح غرفة القسم';b.onclick=()=>{let room=state.discussions.find(r=>r.type==='DEPARTMENT'&&r.department===name);if(!room){room={id:'dept-'+Date.now(),type:'DEPARTMENT',title:'غرفة قسم '+name,project:null,department:name,participants:['nawaf',...state.employees.filter(e=>e.department===name).map(e=>e.id)],messages:[]};state.discussions.push(room);save();}discussionView(room.id)};dialog.appendChild(b);}}
  window.approve=function(action,id){const d=state.decisions.find(x=>x.id===id);if(!d)return;d.status=action==='approve'?'APPROVED':action==='changes'?'CHANGES_REQUESTED':'REJECTED';audit('نواف حدّث القرار: '+d.title+' — '+d.status,'REAL',{project:d.project,decision:id});if(action!=='changes')state.decisions=state.decisions.filter(x=>x.id!==id);save();render();toast('تم تسجيل قرار نواف');}
  window.advance=commandView;
  window.render=function(){baseRender();const button=$("#advance");button.textContent=state.meta.started?'إصدار توجيه جديد ←':'بسم الله — ابدأ العمل';button.onclick=commandView;const greeting=document.querySelector('.greeting');if(greeting&&!document.querySelector('.truth-banner'))greeting.insertAdjacentHTML('afterend','<div class="truth-banner"><span>الحالة: '+(state.meta.started?'بدأ العمل بأوامر موثقة':'شركة نظيفة — لا يوجد عمل بعد')+'</span><span>GitHub: قراءة حقيقية مجانية</span><span>نموذج AI: غير متصل</span></div>');const nav=document.querySelector('.nav');if(nav&&!$("#company-chat")){const b=document.createElement('button');b.id='company-chat';b.textContent='◉ مجلس الشركة';b.onclick=companyChat;nav.insertBefore(b,$("#add"));}document.querySelectorAll('.feed > div').forEach((el,i)=>{const a=state.activities[i];if(a)el.dataset.audit=a.id;});};
  window.add=function(){throw new Error("Legacy synthetic events are disabled")};
  document.addEventListener('click',e=>{const row=e.target.closest('[data-audit]');if(row){const a=state.activities.find(x=>x.id===row.dataset.audit);if(a?.links?.artifact)return artifactView(a.links.artifact);if(a?.links?.discussion)return discussionView(a.links.discussion);if(a?.links?.task)return taskDetail(a.links.task);}const p=e.target.closest('[data-proposal]');if(p)return proposalView(p.dataset.proposal);});
  render();
})();
